from __future__ import absolute_import, division, print_function, \
    unicode_literals
from builtins import object
from future import standard_library
import subprocess
from time import sleep

standard_library.install_aliases()


class KeyEvents(object):

    def __init__(self, mobile_adb_id, total_no_of_retries_change_band=6, total_no_of_retries_attach=6):
        self.total_no_of_retries_change_band = total_no_of_retries_change_band
        self.total_no_of_retries_attach = total_no_of_retries_attach
        self.mobile_adb_id = mobile_adb_id

    def select_item(self, value):
        self.go_to_key_event_in_menu()
        self.enter_key_event(value)
        sleep(10)

    def go_to_key_event_in_menu(self):
        key_list = ["KEYCODE_DPAD_CENTER", "KEYCODE_DPAD_DOWN", "KEYCODE_DPAD_DOWN", "KEYCODE_DPAD_CENTER"]
        self.key_event_sequence(key_list)

    def enter_key_event(self, input_text_value):
        subprocess.check_output("adb -s {0} shell input text {1}".format(
            self.mobile_adb_id, input_text_value), shell=True)
        key_list = ["KEYCODE_DPAD_DOWN", "KEYCODE_DPAD_RIGHT", "KEYCODE_DPAD_CENTER"]
        self.key_event_sequence(key_list)

    def go_to_back_in_menu(self):
        key_list = ["KEYCODE_DPAD_CENTER", "KEYCODE_DPAD_DOWN", "KEYCODE_DPAD_CENTER"]
        self.key_event_sequence(key_list)

    def key_event_sequence(self, key_list):
        for key in key_list:
            self.dial_key(key)

    def dial_key(self, key):
        subprocess.check_output("adb -s {0} shell input keyevent {1}".format(
            self.mobile_adb_id, key), shell=True)
